sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float brightness;
uniform float contrast;
uniform float pivot;
uniform float scurve;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float k = contrast >= 0.0 ? 1.0 + contrast * 3.0 : 1.0 + contrast;
    float3 o = (s + brightness - pivot) * k + pivot;
    float3 t = saturate(o);
    o = mix(o, t * t * (3.0 - 2.0 * t), scurve);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
